const replacementChars = chars.split("");
replacementChars[43] = "AV";

var content = String(result).replace(/<i class="icon icon-uni([0-9a-fA-F]{4})"><\/i>/g, (_, p1) =>
  String.fromCharCode(parseInt(p1, 16))
);

content = content.replace(/[\uE001-\uE101]/g, char => {
  let code = char.charCodeAt(0);
  return replacementChars[code - 0xE001];
});
</js>

