ruleSearch.bookList:
.grid@tag.tr!0<js>
result
  .toArray()
  .slice(0, 3)
  .map(function (el) {
    var url = el.select('a').eq(0).attr('href');

    return {
      name: el.select('a').eq(0).text(),
      author: el.select('td').eq(2).text(),
      kind: el.select('td').eq(5).text(),
      wordCount: el.select('td').eq(3).text(),
      latest: el.select('a').eq(1).text() + ' ' + String(el.select('td').eq(4).text()).replace(/\d+-(\d+-\d+).*/, '$1').replace(new RegExp('(·s*)?([^\\d-])?(\\d{2})?' +String(new Date().getFullYear()).slice(-2) +'-'),'$1$2'),
      url: url,
    };
  });
</js>

